<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue';
import Icon from './HelmLabIcon.vue';
import Confirm from './LocalLabConfirm.vue';
import Grid from './CacheLabGrid.vue';
import RancherTargetPicker from './RancherTargetPicker.vue';
import RancherTokenGenerator from './RancherTokenGenerator.vue';
import {rancherConnectionURL,rancherCredentialAvailable} from './rancher-connection.mjs';
import JsonValue from './CacheLabValue.vue';
import { apiFetch, token as panelToken, setActivePanelTab, cacheWorkspaceIntent } from './store.js';
import { writeTextToClipboard } from './clipboard.js';
import { cacheBytes, cacheDate, quoteTable, cacheCSV, cacheView, cachePair, cacheWorkspaceAfterRefresh } from './cache-lab.mjs';
const props=defineProps({active:{type:Boolean,default:true}});
const library=ref({workspaces:[],snapshots:[],job:{}}), loaded=ref(false), root=ref(''), keychain=ref(false), selectedWorkspace=ref('');
const error=ref(''),notice=ref(''),pending=ref(''),loading=ref(false),querying=ref(false),comparing=ref(false);
const view=reactive(cacheView()),schema=ref([]),result=ref(null),diff=ref(null),row=ref(null),pods=ref([]),pod=ref('');
const connectionBusy=ref(false),autofilledName=ref(''),authMode=ref('password');
const sourceForm=ref(false),editing=ref(false),token=ref(''),draft=reactive({}),sourceFormRef=ref(null),fileInput=ref(null);
const snapshotSearch=ref(''),tableSearch=ref(''),rowSearch=ref(''),rowSort=ref(''),descending=ref(false),page=ref(0),folderName=ref(''),renamedFolder=ref(''),queryName=ref('');
const queryResult=ref(null),snapshotEditing=ref(false),snapshotDraft=reactive({}),confirmation=ref(null),captureName=ref(''),captureNotes=ref('');
const workspace=computed(()=>library.value.workspaces.find(w=>w.id===selectedWorkspace.value));
const credentialAvailable=computed(()=>rancherCredentialAvailable(token.value,draft,editing.value?workspace.value:null));
const sourceReady=computed(()=>draft.kind!=='rancher'||credentialAvailable.value);
const connectionMethods=[{id:'password',kind:'rancher',name:'URL + password',icon:'lock'},{id:'token',kind:'rancher',name:'URL + API token',icon:'key'},{id:'kubeconfig',kind:'kubeconfig',name:'Kubeconfig',icon:'server'},{id:'import',kind:'import',name:'Local files',icon:'folder'}];
const connectionMethod=computed(()=>draft.kind==='rancher'?authMode.value:draft.kind);
const snapshots=computed(()=>library.value.snapshots.filter(s=>s.workspace===selectedWorkspace.value).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)));
const visibleSnapshots=computed(()=>snapshots.value.filter(s=>(!view.folder || (view.folder==='__unfiled__' ? !s.folder : s.folder===view.folder)) && `${s.name} ${s.notes} ${s.pod || ''}`.toLowerCase().includes(snapshotSearch.value.toLowerCase())));
const snapshot=computed(()=>snapshots.value.find(s=>s.id===view.snapshot));
const tables=computed(()=>schema.value.filter(t=>t.name.toLowerCase().includes(tableSearch.value.toLowerCase())));
const table=computed(()=>schema.value.find(t=>t.name===view.table));
const totalBytes=computed(()=>library.value.snapshots.reduce((sum,s)=>sum+s.bytes,0));
const workspaceBytes=computed(()=>snapshots.value.reduce((sum,s)=>sum+s.bytes,0));
const job=computed(()=>library.value.job || {});
const live=computed(()=>['rancher','kubeconfig'].includes(workspace.value?.kind));
const captureBlocked=computed(()=>!!pending.value||job.value.running||!pod.value||!workspace.value?.connected);
const baseline=computed(()=>snapshots.value.find(s=>s.id===view.baseline));
const comparison=computed(()=>snapshots.value.find(s=>s.id===view.comparison));
let disposed=false,pollTimer,viewTimer,noticeTimer,searchTimer,schemaGeneration=0,rowsGeneration=0,diffGeneration=0,queryGeneration=0,initializing=false,refreshGeneration=0;
const controllers=new Set();let queryController,diffController;
let autoCompare=null;
async function request(action,data={}, {timeout=30000,signal}={}) {
 const controller=new AbortController();controllers.add(controller);const abort=()=>controller.abort();signal?.addEventListener('abort',abort,{once:true});if(signal?.aborted)abort();
 const timer=setTimeout(()=>controller.abort(),timeout);
 try {const response=await apiFetch('/api/cache-lab',action?{method:'POST',body:JSON.stringify({action,...data}),signal:controller.signal}:{signal:controller.signal});if(!response.ok)throw new Error((await response.text())||'Cache Lab request failed.');return await response.json();}
 catch(failure){if(failure.name==='AbortError')throw new Error('Request stopped or timed out. Saved snapshots are unchanged.');throw failure;}
 finally {clearTimeout(timer);controllers.delete(controller);signal?.removeEventListener('abort',abort);}
}
function inform(text){notice.value=text;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>notice.value='',7000);}
async function refresh() {
 clearTimeout(pollTimer);const generation=++refreshGeneration;
 try {const state=await request();if(disposed||generation!==refreshGeneration)return;const previousJob=library.value.job;library.value=state.library;root.value=state.root;keychain.value=state.keychain;loaded.value=true;
  const intent=props.active?cacheWorkspaceIntent.value:'';
  const nextWorkspace=cacheWorkspaceAfterRefresh(library.value,selectedWorkspace.value,{formOpen:sourceForm.value,intent});
  if(nextWorkspace!==null){chooseWorkspace(nextWorkspace);if(nextWorkspace===intent)cacheWorkspaceIntent.value='';}
  if(autoCompare && !job.value.running && job.value.id===autoCompare.job){const intent=autoCompare;autoCompare=null;if(job.value.snapshot&&selectedWorkspace.value===intent.workspace){view.snapshot=job.value.snapshot;view.baseline=intent.baseline;view.comparison=job.value.snapshot;view.mode='compare';await compare();inform('New snapshot captured. Your comparison is ready.');}}
  if(previousJob?.running && !job.value.running && previousJob.id===job.value.id && job.value.snapshot && job.value.workspace===selectedWorkspace.value)view.snapshot=job.value.snapshot;
  if(job.value.snapshot && !view.snapshot && job.value.workspace===selectedWorkspace.value)view.snapshot=job.value.snapshot;
 }catch(failure){if(!disposed)error.value=failure.message;}
 finally{if(!disposed && props.active && generation===refreshGeneration)pollTimer=setTimeout(refresh,job.value.running?1500:12000);}
}
function chooseWorkspace(id) {
 if(connectionBusy.value)return;
 flushView();diffController?.abort();diffGeneration++;comparing.value=false;queryController?.abort();queryGeneration++;querying.value=false;initializing=true;selectedWorkspace.value=id;Object.assign(view,cacheView(workspace.value?.view));if(!view.snapshot && snapshots.value.length)view.snapshot=snapshots.value[0].id;
 row.value=null;schema.value=[];result.value=null;diff.value=null;queryResult.value=null;pods.value=[];pod.value=workspace.value?.pod||'';snapshotSearch.value='';tableSearch.value='';rowSearch.value='';sourceForm.value=false;confirmation.value=null;snapshotEditing.value=false;initializing=false;
 if(id){persistView();loadSchema();if(view.mode==='compare')compare();}
}
function persistView(){if(initializing||!workspace.value)return;clearTimeout(viewTimer);viewTimer=setTimeout(flushView,450);}
async function flushView(){clearTimeout(viewTimer);if(!workspace.value||initializing)return;const id=selectedWorkspace.value;const saved={...view};const w=workspace.value;w.view=saved;try{await request('view',{workspace:id,view:saved});}catch(failure){if(!disposed)error.value=`Could not save workspace state: ${failure.message}`;}}
watch(view,persistView,{deep:true});
watch(()=>view.snapshot,()=>{if(!initializing){snapshotEditing.value=false;row.value=null;queryResult.value=null;queryController?.abort();queryGeneration++;querying.value=false;loadSchema();}});
async function action(action,data={},message='') {
 if(pending.value)return null;pending.value=action;error.value='';
 try {const value=await request(action,{workspace:selectedWorkspace.value,...data},{timeout:action==='discover'?40000:30000});await refresh();if(message)inform(message);return value;}
 catch(failure){error.value=failure.message;return null;}
 finally{pending.value='';}
}
function newSource(kind='rancher') {if(connectionBusy.value)return;autofilledName.value='';authMode.value='password';editing.value=false;token.value='';Object.keys(draft).forEach(key=>delete draft[key]);Object.assign(draft,{kind,name:'',url:'',namespace:'cattle-system',container:'rancher',cluster:'local',kubeconfig:'',context:'',rememberToken:false,insecure:false,caPem:'',helperPath:''});sourceForm.value=true;nextTick(()=>sourceFormRef.value?.querySelector('input')?.focus());}
function editSource(){if(connectionBusy.value)return;editing.value=true;authMode.value='password';token.value='';Object.keys(draft).forEach(key=>delete draft[key]);Object.assign(draft,workspace.value);sourceForm.value=true;nextTick(()=>sourceFormRef.value?.scrollIntoView({block:'nearest'}));}
async function saveSource(){if(connectionBusy.value||!sourceReady.value)return;const value=await action('save-workspace',{profile:{...draft},token:token.value},'Workspace saved.');if(!value)return;token.value='';sourceForm.value=false;chooseWorkspace(value.id);if(['rancher','kubeconfig'].includes(value.kind))await discover();}
function changeConnection(item){if(connectionBusy.value||pending.value||(editing.value&&draft.kind!==item.kind))return;if(draft.kind!==item.kind)token.value='';draft.kind=item.kind;if(item.kind==='rancher')authMode.value=item.id;}
function useRancherTarget({target,kind}) {
 if(connectionBusy.value)return;
 const changed=rancherConnectionURL(draft.url)!==target.url;
 if(changed){token.value='';draft.insecure=false;draft.caPem='';}
 draft.url=target.url;draft.kind=kind;draft.cluster='local';
 if(!draft.name||draft.name===autofilledName.value)draft.name=target.name;autofilledName.value=target.name;
 if(kind==='kubeconfig'){token.value='';draft.kubeconfig=target.kubeconfig;draft.context='';draft.rememberToken=false;}
 nextTick(()=>sourceFormRef.value?.querySelector(kind==='kubeconfig'?'input':'input[type=password]')?.focus({preventScroll:true}));
 inform(kind==='kubeconfig'?'Management kubeconfig selected. No Rancher token is needed.':'Rancher selected. Sign in with your password, or choose the API token tab.');
}
watch(()=>draft.url,(value,previous)=>{if(sourceForm.value && rancherConnectionURL(value)!==rancherConnectionURL(previous))token.value='';});
async function discover(){const id=selectedWorkspace.value;const response=await action('discover');if(response&&id===selectedWorkspace.value){pods.value=response.pods;if(!pods.value.some(p=>p.name===pod.value))pod.value=pods.value[0]?.name||'';if(!pods.value.length)inform('No running containers matched this namespace and container name. Review the connection settings.');}}
async function capture(compareAfter=false){const id=selectedWorkspace.value;const before=view.snapshot;const response=await action('capture',{profile:{pod:pod.value},name:captureName.value,notes:captureNotes.value,folder:view.folder==='__unfiled__'?'':view.folder});if(response){if(compareAfter&&before)autoCompare={workspace:id,baseline:before,job:response.job};captureName.value='';captureNotes.value='';inform('Capture started. You can keep exploring saved snapshots.');}}
async function importFile(event) {const file=event.target.files?.[0];event.target.value='';if(!file||pending.value)return;if(file.size>2*1024**3){error.value='Choose a SQLite file smaller than 2 GiB.';return;}pending.value='import';error.value='';const controller=new AbortController();controllers.add(controller);const timer=setTimeout(()=>controller.abort(),8*60*1000);
 try {const body=new FormData();body.append('file',file);const response=await fetch(`/api/cache-lab/import?workspace=${encodeURIComponent(selectedWorkspace.value)}`,{method:'POST',body,signal:controller.signal,headers:{'X-Control-Panel-Token':panelToken}});if(!response.ok)throw new Error(await response.text());const saved=await response.json();await refresh();if(saved.workspace===selectedWorkspace.value)view.snapshot=saved.id;inform('Snapshot imported and validated.');}catch(failure){error.value=failure.message;}finally{clearTimeout(timer);controllers.delete(controller);pending.value='';}
}
async function loadSchema(){const generation=++schemaGeneration;++rowsGeneration;schema.value=[];result.value=null;row.value=null;page.value=0;rowSort.value='';rowSearch.value='';if(!snapshot.value)return;loading.value=true;const id=view.snapshot;
 try{const response=await request('schema',{snapshot:id});if(generation!==schemaGeneration||id!==view.snapshot)return;schema.value=response.tables;if(!schema.value.some(t=>t.name===view.table))view.table=schema.value[0]?.name||'';if(view.table)await loadRows();}
 catch(failure){if(generation===schemaGeneration)error.value=failure.message;}finally{if(generation===schemaGeneration)loading.value=false;}
}
function chooseTable(name){view.table=name;page.value=0;row.value=null;rowSort.value='';loadRows();}
async function loadRows(){if(!snapshot.value||!view.table)return;const generation=++rowsGeneration;loading.value=true;result.value=null;
 try{const response=await request('rows',{snapshot:view.snapshot,table:view.table,search:rowSearch.value,sort:rowSort.value,desc:descending.value,offset:page.value*100});if(generation===rowsGeneration)result.value=response;}
 catch(failure){if(generation===rowsGeneration)error.value=failure.message;}finally{if(generation===rowsGeneration)loading.value=false;}
}
function searchRows(){clearTimeout(searchTimer);page.value=0;searchTimer=setTimeout(loadRows,300);}
function sortRows(name){descending.value=rowSort.value===name?!descending.value:false;rowSort.value=name;page.value=0;loadRows();}
async function runQuery(){queryController?.abort();queryController=new AbortController();const generation=++queryGeneration;querying.value=true;error.value='';queryResult.value=null;row.value=null;
 try{const value=await request('query',{snapshot:view.snapshot,sql:view.sql},{signal:queryController.signal});if(generation===queryGeneration)queryResult.value=value;}catch(failure){if(generation===queryGeneration)error.value=failure.message;}finally{if(generation===queryGeneration)querying.value=false;}
}
function changeMode(mode){view.mode=mode;row.value=null;if(mode==='sql'&&!view.sql&&view.table)view.sql=`SELECT *\nFROM ${quoteTable(view.table)}\nLIMIT 100;`;if(mode==='compare'){if(!view.compareTable)view.compareTable=view.table;if(!view.baseline||!view.comparison)Object.assign(view,cachePair(snapshots.value,view.snapshot));compare();}}
async function compare(){diffController?.abort();const generation=++diffGeneration;diff.value=null;row.value=null;comparing.value=false;if(!view.baseline||!view.comparison||view.baseline===view.comparison)return;diffController=new AbortController();comparing.value=true;error.value='';
 try{const response=await request('diff',{snapshot:view.baseline,other:view.comparison,table:view.compareTable,ignoreVolatile:view.ignoreVolatile},{timeout:70000,signal:diffController.signal});if(generation===diffGeneration)diff.value=response;}
 catch(failure){if(generation===diffGeneration)error.value=failure.message;}finally{if(generation===diffGeneration)comparing.value=false;}
}
function pairChanged(){view.compareTable='';compare();}
async function saveQuery(){const value=await action('save-query',{name:queryName.value,sql:view.sql},'Query saved in this workspace.');if(value)queryName.value='';}
async function renameFolder(){const name=renamedFolder.value.trim();const response=await action('rename-folder',{folder:view.folder,name},'Folder renamed.');if(response){view.folder=name;renamedFolder.value='';}}
async function makeFolder(){const name=folderName.value.trim();if(!name)return;const value=await action('folder',{name},'Folder created.');if(value){folderName.value='';view.folder=name;}}
function editSnapshot(){Object.assign(snapshotDraft,snapshot.value);snapshotEditing.value=true;}
async function saveSnapshot(){const value=await action('snapshot',{snapshot:snapshotDraft.id,name:snapshotDraft.name,notes:snapshotDraft.notes,folder:snapshotDraft.folder,favorite:snapshotDraft.favorite},'Snapshot details saved.');if(value)snapshotEditing.value=false;}
async function favorite(){await action('snapshot',{snapshot:snapshot.value.id,name:snapshot.value.name,notes:snapshot.value.notes,folder:snapshot.value.folder,favorite:!snapshot.value.favorite});}
async function exportSnapshot(){const response=await action('export',{snapshot:view.snapshot});if(response)inform(`Database saved to ${response.path}`);}
function download(value,name,type='application/json'){const url=URL.createObjectURL(new Blob([value],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
async function copy(value){try{await writeTextToClipboard(typeof value==='string'?value:JSON.stringify(value,null,2));inform('Copied to clipboard.');}catch{error.value='Clipboard access is unavailable. Select the text to copy it.';}}
function confirmDelete(kind){const snapshotDelete=kind==='delete-snapshot';confirmation.value={action:kind,workspace:selectedWorkspace.value,snapshot:view.snapshot,folder:view.folder,phrase:snapshotDelete?'delete snapshot':kind==='delete-workspace'?'delete workspace':kind==='delete-folder'?'remove folder':'delete snapshots',title:snapshotDelete?'Delete this snapshot?':kind==='delete-workspace'?`Delete ${workspace.value.name}?`:kind==='delete-folder'?'Remove this folder?':'Clear saved snapshots?',message:snapshotDelete?`Permanently remove “${snapshot.value.name}” from this library.`:kind==='delete-folder'?'Snapshots in this folder will move to Unfiled. Their files are preserved.':`${snapshots.value.length} snapshots (${cacheBytes(workspaceBytes.value)}) will be permanently removed from this workspace.${kind==='delete-workspace'?' The connection, saved credential, queries, and notes will also be removed.':''} Live Rancher resources and original imported files are unaffected.`};}
async function remove(){const c=confirmation.value;if(!c)return;const value=await action(c.action,{workspace:c.workspace,snapshot:c.snapshot,folder:c.folder,confirm:c.phrase},'Cleanup finished.');if(value){confirmation.value=null;if(!snapshots.value.some(s=>s.id===view.snapshot))view.snapshot=snapshots.value[0]?.id||'';if(!snapshots.value.some(s=>s.id===view.baseline))view.baseline='';if(!snapshots.value.some(s=>s.id===view.comparison))view.comparison='';if(c.action==='delete-folder')view.folder='';}}
function sourceKeys(event,index){if(!['ArrowRight','ArrowLeft','Home','End'].includes(event.key))return;event.preventDefault();const count=library.value.workspaces.length;const next=event.key==='Home'?0:event.key==='End'?count-1:(index+(event.key==='ArrowRight'?1:-1)+count)%count;chooseWorkspace(library.value.workspaces[next].id);nextTick(()=>document.getElementById(`cache-source-${next}`)?.focus());}
watch(()=>props.active,active=>{clearTimeout(pollTimer);if(active)refresh();else flushView();});
function saveOnExit(){if(!workspace.value)return;fetch('/api/cache-lab',{method:'POST',keepalive:true,headers:{'Content-Type':'application/json','X-Control-Panel-Token':panelToken},body:JSON.stringify({action:'view',workspace:selectedWorkspace.value,view:{...view}})}).catch(()=>{});}
onMounted(()=>{refresh();window.addEventListener('pagehide',saveOnExit);});
onBeforeUnmount(()=>{saveOnExit();window.removeEventListener('pagehide',saveOnExit);disposed=true;clearTimeout(pollTimer);clearTimeout(viewTimer);clearTimeout(noticeTimer);clearTimeout(searchTimer);controllers.forEach(c=>c.abort());});
</script>

<template>
 <div class="cache-lab local-lab">
  <header class="cache-masthead"><div class="cache-brand"><div class="cache-emblem"><Icon name="database" /></div><div><span class="lab-eyebrow">RANCHER RUNWAY / CACHE OBSERVATORY</span><h2>Cache Lab<span class="cache-period">.</span></h2><p>Capture a moment. Understand what changed.</p></div></div><div class="cache-head-actions"><span>{{ library.workspaces.length }} {{ library.workspaces.length===1?'source':'sources' }} <i>·</i> {{ library.snapshots.length }} snapshots <i>·</i> {{ cacheBytes(totalBytes) }}</span><button type="button" class="lab-primary" :disabled="connectionBusy" @click="newSource()"><Icon name="plus" />New workspace</button></div></header>
  <div v-if="error" class="cache-message" role="alert" data-tone="error"><Icon name="signal" /><span>{{ error }}</span><button type="button" aria-label="Dismiss error" @click="error=''">×</button></div>
  <div v-if="notice" class="cache-message" role="status"><Icon name="check" /><span>{{ notice }}</span><button type="button" aria-label="Dismiss notification" @click="notice=''">×</button></div>
  <div v-if="!loaded" class="cache-loading" role="status"><Icon name="refresh" class="lab-spin" />Opening your snapshot library…</div>
  <div v-if="library.workspaces.length" class="cache-source-tabs" role="tablist" aria-label="Rancher workspaces"><button v-for="(source,index) in library.workspaces" :id="`cache-source-${index}`" :key="source.id" type="button" role="tab" :aria-selected="source.id===selectedWorkspace" :tabindex="source.id===selectedWorkspace?0:-1" aria-controls="cache-workspace" :disabled="connectionBusy" @click="chooseWorkspace(source.id)" @keydown="sourceKeys($event,index)"><Icon :name="source.kind==='import'?'folder':source.kind==='steve'?'flask':'globe'" /><span><strong>{{ source.name }}</strong><small>{{ source.url }}</small></span><span class="cache-count">{{ library.snapshots.filter(s=>s.workspace===source.id).length }}</span></button></div>

  <form v-if="sourceForm" ref="sourceFormRef" class="cache-connect" @submit.prevent="saveSource">
   <div class="cache-section-heading"><div><span class="lab-eyebrow">{{ editing?'CONNECTION SETTINGS':'A HOME FOR YOUR INVESTIGATION' }}</span><h3>{{ editing?'Edit workspace':'Connect a source' }}</h3><p>Names and snapshots stay with this workspace when you reopen Runway.</p></div><button type="button" aria-label="Close connection settings" :disabled="connectionBusy" @click="sourceForm=false;token='' "><Icon name="close" /></button></div>
   <div v-if="draft.kind!=='steve'" class="rancher-methods" role="group" aria-label="Connection method"><button v-for="item in connectionMethods" :key="item.id" type="button" :aria-pressed="connectionMethod===item.id" :disabled="!!pending||connectionBusy||(editing&&draft.kind!==item.kind)" @click="changeConnection(item)"><Icon :name="item.icon"/>{{ item.name }}</button></div>
   <RancherTargetPicker v-if="!editing && ['rancher','kubeconfig'].includes(draft.kind)" purpose="cache" :url="draft.url" :disabled="!!pending||connectionBusy" @select="useRancherTarget"/>
   <fieldset :disabled="!!pending||connectionBusy" class="cache-connect-fields"><legend class="lab-sr-only">Connection details</legend>
    <label v-if="draft.kind==='rancher'" class="cache-full rancher-connection-url">Rancher URL<input v-model="draft.url" type="url" placeholder="https://rancher.example.com" required autocomplete="off" spellcheck="false"></label>
    <label v-if="draft.kind==='rancher'&&authMode==='token'" class="cache-full">API token<input v-model="token" type="password" :placeholder="credentialAvailable&&!token?'Leave blank to keep the current token':'token-xxxxx:secret'" :required="!credentialAvailable" autocomplete="off"><small>For a local account or SSO, paste a user token from Rancher’s API &amp; Keys.</small></label>
    <label v-if="draft.kind==='kubeconfig'">Kubeconfig path<input v-model="draft.kubeconfig" placeholder="/Users/you/.kube/config" required spellcheck="false"><small>Use a trusted local kubeconfig. Its selected context supplies the source URL.</small></label>
    <label v-if="draft.kind==='kubeconfig'">Context <span class="cache-optional">optional</span><input v-model="draft.context" placeholder="Use current context" spellcheck="false"></label>
   </fieldset>
   <RancherTokenGenerator v-if="draft.kind==='rancher'&&authMode==='password'" purpose="cache" :url="draft.url" :credential-available="credentialAvailable" :insecure="draft.insecure" :ca-pem="draft.caPem" :disabled="!!pending" @busy="connectionBusy=$event" @generated="token=$event.token"/>
   <fieldset :disabled="!!pending||connectionBusy" class="cache-connect-fields"><legend class="lab-sr-only">Workspace preferences</legend>
    <label v-if="draft.kind==='rancher' && keychain" class="cache-check cache-full"><input v-model="draft.rememberToken" type="checkbox">Remember token in macOS Keychain<small>Reconnect after restarting Runway when this is off. Snapshots remain available.</small></label>
    <details class="cache-advanced cache-full" :open="draft.kind!=='rancher'"><summary><Icon name="folder"/>Workspace details <span class="cache-optional">· nickname &amp; notes</span></summary><div class="cache-connect-fields"><label>Nickname <span class="cache-optional">optional</span><input v-model="draft.name" maxlength="120" :placeholder="draft.kind==='import'?'My investigation':'Defaults to the source hostname'"></label><label>Workspace notes <span class="cache-optional">optional</span><input v-model="draft.notes" maxlength="8000" placeholder="What are you investigating?"></label></div></details>
    <details v-if="['rancher','kubeconfig'].includes(draft.kind)" class="cache-advanced cache-full"><summary><Icon name="sliders"/>Connection settings <span class="cache-optional">· {{ draft.kind==='rancher'?'TLS, namespace & helper':'namespace & helper' }}</span></summary><div class="cache-connect-fields"><label v-if="draft.kind==='rancher'" class="cache-full">Custom CA certificate<textarea v-model="draft.caPem" rows="3" placeholder="-----BEGIN CERTIFICATE-----" spellcheck="false"></textarea></label><label v-if="draft.kind==='rancher'" class="cache-check cache-full"><input v-model="draft.insecure" type="checkbox">Skip TLS verification for this connection<small>Only use with a server you trust. A custom CA is preferred.</small></label><label>Namespace<input v-model="draft.namespace" required></label><label>Container name<input v-model="draft.container" required></label><label v-if="draft.kind==='rancher'">Management cluster ID<input v-model="draft.cluster" placeholder="local"></label><label>Helper binary <span class="cache-optional">optional</span><input v-model="draft.helperPath" placeholder="Verified release is downloaded automatically"><small>For ARM pods or offline use, choose a matching Linux vai-vacuum binary by full local path.</small></label></div></details>
   </fieldset>
   <div class="cache-form-footer"><p>{{ draft.kind==='rancher'&&!credentialAvailable?'Sign in or add an API token to create this workspace.':draft.kind==='import'?'Import standalone SQLite snapshots, including exports from other tools.':'Live capture needs pod discovery and exec access to the cluster hosting Rancher.' }}</p><button type="submit" class="lab-primary" :disabled="!!pending||connectionBusy||!sourceReady">{{ pending==='save-workspace'?'Saving…':editing?'Save connection':'Create workspace' }}<Icon name="arrow" /></button></div>
  </form>

  <div v-if="loaded && !workspace && !sourceForm" class="cache-welcome"><div class="cache-constellation" aria-hidden="true"><span><Icon name="database" /></span><i></i><span><Icon name="branch" /></span><i></i><span><Icon name="eye" /></span></div><span class="lab-eyebrow">MAKE THE INVISIBLE VISIBLE</span><h3>A little clarity, one snapshot at a time.</h3><p>Bring a live Rancher cache or a saved SQLite file.<br>Give each investigation its own place, then explore what changed.</p><div class="cache-welcome-actions"><button type="button" class="lab-primary" @click="newSource('rancher')"><Icon name="globe" />Connect Rancher</button><button type="button" @click="newSource('import')"><Icon name="upload" />Start with a file</button></div><div class="cache-principles"><div><b>01</b><strong>Capture with confidence</strong><span>Consistent copies through VACUUM INTO.</span></div><div><b>02</b><strong>Follow your curiosity</strong><span>Tables, JSON objects, and saved SQL queries.</span></div><div><b>03</b><strong>See the difference</strong><span>Before and after, down to the changed field.</span></div></div><button type="button" class="lab-text-button" @click="setActivePanelTab('steve')">Working locally? Capture directly from Steve Lab <Icon name="arrow" /></button></div>

  <section v-if="workspace" id="cache-workspace" class="cache-source-workspace" role="tabpanel" :aria-label="workspace.name">
   <div class="cache-source-heading"><div><span class="lab-eyebrow">{{ workspace.kind==='import'?'LOCAL FILE COLLECTION':workspace.kind==='steve'?'STEVE LAB SOURCE':'RANCHER SOURCE' }}</span><h3>{{ workspace.name }}</h3><p class="cache-source-url">{{ workspace.url }}<span v-if="workspace.context"> · {{ workspace.context }}</span></p><p v-if="workspace.notes">{{ workspace.notes }}</p></div><div class="lab-button-row"><button v-if="workspace" type="button" @click="editSource"><Icon name="sliders" />Connection</button><button type="button" :disabled="!!pending || job.running" @click="fileInput.click()"><Icon name="upload" />Import .db</button><details class="cache-menu"><summary aria-label="Workspace options"><Icon name="folder" />Manage</summary><div><p>{{ snapshots.length }} snapshots · {{ cacheBytes(workspaceBytes) }}</p><button type="button" :disabled="job.running || !snapshots.length" @click="confirmDelete('clear-workspace')">Clear snapshots…</button><button type="button" :disabled="job.running" @click="confirmDelete('delete-workspace')">Delete workspace…</button></div></details></div></div>
   <input ref="fileInput" class="cache-file-input" type="file" accept=".db,.sqlite,.sqlite3,application/vnd.sqlite3,application/x-sqlite3" aria-label="Import SQLite snapshot" @change="importFile">
   <div v-if="live" class="cache-capture-bar"><div class="cache-capture-symbol"><Icon name="database" /></div><div class="cache-capture-content"><strong>Take a fresh look</strong><p>Snapshot one Rancher replica. Explore your saved copies while it runs.</p><div class="cache-capture-fields"><label class="lab-sr-only" for="cache-pod">Rancher pod</label><select id="cache-pod" v-model="pod" @change="action('select-pod',{name:pod})" :disabled="!!pending || job.running"><option value="">Choose a Rancher pod</option><option v-if="pod && !pods.some(p=>p.name===pod)" :value="pod">{{ pod }} · last selected</option><option v-for="item in pods" :key="item.uid" :value="item.name">{{ item.name }}{{ item.ready?'':' · not ready' }}</option></select><button type="button" :disabled="!!pending || job.running || !workspace.connected" @click="discover"><Icon name="refresh" :class="{'lab-spin':pending==='discover'}" />{{ pending==='discover'?'Discovering…':'Find pods' }}</button><input v-model="captureName" aria-label="New snapshot name" placeholder="Snapshot name · optional" maxlength="140"></div><p v-if="!workspace.connected" class="cache-warning">Reconnect to capture again. Your saved snapshots are ready to explore.</p></div><div class="cache-capture-actions"><button type="button" class="lab-primary" :disabled="captureBlocked" @click="capture(false)"><Icon name="download" />Capture snapshot</button><button v-if="snapshot" type="button" :disabled="captureBlocked" @click="capture(true)"><Icon name="branch" />Capture again & compare</button></div></div>
   <div v-if="workspace.kind==='steve'" class="cache-steve-note"><Icon name="flask" /><span>Snapshots from your local Steve session live here. Capture again from the session card in Steve Lab.</span><button type="button" @click="setActivePanelTab('steve')">Open Steve Lab<Icon name="arrow" /></button></div>
   <div v-if="job.workspace===selectedWorkspace && (job.running || job.error)" class="cache-job" :data-error="!!job.error" role="status"><Icon :name="job.running?'refresh':'signal'" :class="{'lab-spin':job.running}" /><div><strong>{{ job.stage }}</strong><span>{{ job.error || 'The source database stays unchanged. Keep Runway open until capture finishes.' }}</span></div><button v-if="job.running" type="button" :disabled="pending==='cancel'" @click="action('cancel')">Cancel capture</button></div>
   <Confirm v-if="confirmation" :key="confirmation.action+confirmation.snapshot" :title="confirmation.title" :message="confirmation.message" :phrase="confirmation.phrase" :busy="!!pending" @confirm="remove" @cancel="confirmation=null" />
   <div class="cache-workbench">
    <aside class="cache-library"><div class="cache-library-title"><span class="lab-eyebrow">SNAPSHOT LIBRARY</span><span class="cache-count">{{ snapshots.length }}</span></div><label class="cache-search"><Icon name="search" /><input v-model="snapshotSearch" aria-label="Search snapshots" placeholder="Find a snapshot…"></label><label class="lab-sr-only" for="cache-folder">Snapshot folder</label><select id="cache-folder" v-model="view.folder"><option value="">All snapshots</option><option value="__unfiled__">Unfiled</option><option v-for="folder in workspace.folders" :key="folder" :value="folder">{{ folder }}</option></select>
     <div class="cache-snapshot-list"><button v-for="item in visibleSnapshots" :key="item.id" type="button" :aria-pressed="view.snapshot===item.id" @click="view.snapshot=item.id;row=null"><span class="cache-snapshot-icon"><Icon name="database" /></span><span><strong>{{ item.favorite?'★ ':'' }}{{ item.name }}</strong><small>{{ cacheDate(item.createdAt) }}</small><small>{{ cacheBytes(item.bytes) }} · {{ item.tables }} {{ item.tables===1?'table':'tables' }}</small></span><i v-if="view.baseline===item.id" title="Comparison baseline">A</i></button><div v-if="!visibleSnapshots.length" class="cache-library-empty"><Icon name="layers" /><p>{{ snapshots.length?'No snapshots match this view.':'Your first snapshot starts the story.' }}</p></div></div>
     <details class="cache-folder-tools"><summary><Icon name="folder" />Organize folders</summary><form @submit.prevent="makeFolder"><label class="lab-sr-only" for="cache-new-folder">New folder name</label><input id="cache-new-folder" v-model="folderName" placeholder="e.g. Provisioning test" maxlength="80"><button type="submit" :disabled="!folderName.trim() || !!pending">Create folder</button></form><form v-if="view.folder && view.folder!=='__unfiled__'" @submit.prevent="renameFolder"><input v-model="renamedFolder" aria-label="Rename selected folder" placeholder="New folder name" maxlength="80"><button type="submit" :disabled="!renamedFolder.trim() || !!pending">Rename folder</button></form><button v-if="view.folder && view.folder!=='__unfiled__'" type="button" @click="confirmDelete('delete-folder')">Remove this folder…</button></details><span class="cache-library-storage"><Icon name="lock" />Saved locally · {{ cacheBytes(workspaceBytes) }}</span>
    </aside>
    <main class="cache-inspector">
     <div v-if="!snapshot" class="cache-empty-inspector"><div class="cache-empty-orbit"><Icon name="database" /></div><span class="lab-eyebrow">READY FOR A CLOSER LOOK</span><h3>{{ snapshots.length?'Choose a snapshot':'Your cache, in focus.' }}</h3><p>{{ snapshots.length?'Select a saved moment from the library to explore its tables, query its contents, or compare it with another.':'Capture from a live pod or import a standalone SQLite file. Your source, snapshots, and notes stay together here.' }}</p><button type="button" :disabled="!!pending || job.running" @click="fileInput.click()"><Icon name="upload" />Import a snapshot</button></div>
     <template v-else>
      <div class="cache-snapshot-heading"><div><span class="lab-eyebrow">{{ snapshot.method }}</span><h3>{{ snapshot.name }}</h3><p>{{ cacheDate(snapshot.createdAt) }} <i>·</i> {{ cacheBytes(snapshot.bytes) }} <i>·</i> {{ snapshot.tables }} {{ snapshot.tables===1?'table':'tables' }}</p></div><div class="lab-button-row"><button type="button" :aria-pressed="snapshot.favorite" :aria-label="snapshot.favorite?'Unfavorite snapshot':'Favorite snapshot'" @click="favorite">{{ snapshot.favorite?'★':'☆' }}</button><button type="button" :disabled="!!pending" @click="exportSnapshot"><Icon name="download" />Export</button><button type="button" aria-label="Delete snapshot" :disabled="!!pending || job.running" @click="confirmDelete('delete-snapshot')"><Icon name="trash" /></button></div></div>
      <details class="cache-provenance"><summary><Icon name="fingerprint" />Snapshot details & notes <span>{{ snapshot.pod || snapshot.source }}</span></summary><div class="cache-provenance-grid"><div><small>Source</small><strong>{{ snapshot.source }}</strong></div><div><small>Rancher / Steve image</small><strong>{{ snapshot.image || 'Not recorded' }}</strong></div><div><small>Pod / restarts</small><strong>{{ snapshot.pod || 'Local file' }}{{ snapshot.pod ? ` / ${snapshot.restarts}` : '' }}</strong></div><div><small>SHA-256</small><code>{{ snapshot.sha256 }}</code></div></div><p v-if="snapshot.notes">{{ snapshot.notes }}</p><div v-if="snapshotEditing" class="cache-snapshot-editor"><label>Name<input v-model="snapshotDraft.name" maxlength="140" required></label><label>Folder<select v-model="snapshotDraft.folder"><option value="">Unfiled</option><option v-for="f in workspace.folders" :key="f" :value="f">{{ f }}</option></select></label><label class="cache-full">Notes<textarea v-model="snapshotDraft.notes" rows="3" maxlength="8000"></textarea></label><div class="lab-button-row cache-full"><button type="button" class="lab-primary" :disabled="!!pending || !snapshotDraft.name.trim()" @click="saveSnapshot">Save details</button><button type="button" @click="snapshotEditing=false">Cancel</button></div></div><button v-else type="button" class="lab-text-button" @click="editSnapshot">Edit name, folder & notes <Icon name="arrow" /></button></details>
      <nav class="cache-mode-tabs" aria-label="Snapshot tools"><button v-for="item in [{id:'explore',label:'Explore',icon:'database'},{id:'sql',label:'SQL workspace',icon:'terminal'},{id:'compare',label:'Compare',icon:'branch'}]" :key="item.id" type="button" :aria-current="view.mode===item.id?'page':undefined" @click="changeMode(item.id)"><Icon :name="item.icon" />{{ item.label }}</button><span><Icon name="lock" />Read-only</span></nav>
      <div v-if="view.mode==='explore'" class="cache-explorer"><aside class="cache-tables"><label class="cache-search"><Icon name="search" /><input v-model="tableSearch" placeholder="Find a table…" aria-label="Search tables"></label><span class="cache-table-count">{{ schema.length }} {{ schema.length===1?'table':'tables' }}</span><div class="cache-table-list"><button v-for="item in tables" :key="item.name" type="button" :aria-pressed="view.table===item.name" @click="chooseTable(item.name)"><Icon name="table" /><span>{{ item.name }}</span></button><p v-if="!tables.length && !loading" class="cache-muted">No tables found.</p></div></aside><div class="cache-table-content"><div class="cache-table-heading"><h4>{{ view.table || 'Select a table' }}</h4><button v-if="view.table" type="button" class="lab-text-button" @click="view.sql=`SELECT *\nFROM ${quoteTable(view.table)}\nLIMIT 100;`;changeMode('sql')">Query this table <Icon name="arrow" /></button></div><details v-if="table" class="cache-schema"><summary>Schema <span>{{ table.columns.length }} columns</span></summary><div class="cache-column-chips"><span v-for="column in table.columns" :key="column.name"><Icon v-if="column.pk" name="key" />{{ column.name }}<small>{{ column.type || 'ANY' }}</small></span></div><pre>{{ table.sql }}{{ table.indexes?.length?'\n\n'+table.indexes.join('\n\n'):'' }}</pre></details><label v-if="view.table" class="cache-search cache-row-filter"><Icon name="search" /><input v-model="rowSearch" placeholder="Filter across columns…" aria-label="Filter table rows" @input="searchRows"></label><div v-if="loading" class="cache-loading" role="status"><Icon name="refresh" class="lab-spin" />Reading snapshot…</div><Grid v-if="result" :result="result" :busy="loading" :sort="rowSort" :descending="descending" @row="row=$event" @sort="sortRows" /><div v-if="result" class="cache-pagination"><span>{{ result.rows.length }} {{ result.rows.length===1?'row':'rows' }} · page {{ page+1 }} <i>·</i> {{ result.elapsedMs }} ms</span><div><button type="button" :disabled="page===0 || loading" @click="page--;loadRows()"><Icon name="arrow-left" /><span class="lab-sr-only">Previous page</span></button><button type="button" :disabled="!result.more || loading" @click="page++;loadRows()"><Icon name="arrow" /><span class="lab-sr-only">Next page</span></button></div></div></div></div>
      <div v-if="view.mode==='sql'" class="cache-sql"><div class="cache-sql-toolbar"><div><strong>Your question, in SQL.</strong><p>Read-only queries · up to 500 rows · 20-second execution limit</p></div><select aria-label="Load a saved query" value="" @change="view.sql=workspace.queries.find(q=>q.name===$event.target.value)?.sql||view.sql;$event.target.value=''"><option value="">Load a saved query…</option><option v-for="q in workspace.queries" :key="q.name" :value="q.name">{{ q.name }}</option></select></div><label class="lab-sr-only" for="cache-query">Read-only SQL query</label><textarea id="cache-query" v-model="view.sql" rows="7" spellcheck="false" placeholder="SELECT * FROM &quot;table_name&quot; LIMIT 100;" @keydown.meta.enter.prevent="runQuery" @keydown.ctrl.enter.prevent="runQuery"></textarea><div class="cache-query-actions"><span><kbd>⌘ / Ctrl</kbd> + <kbd>Enter</kbd> to run</span><button v-if="querying" type="button" @click="queryController?.abort()">Cancel query</button><button type="button" class="lab-primary" :disabled="querying || !view.sql.trim()" @click="runQuery"><Icon :name="querying?'refresh':'play'" :class="{'lab-spin':querying}" />{{ querying?'Running…':'Run query' }}</button></div><details class="cache-saved-queries"><summary><Icon name="bookmark" />Save & manage queries</summary><form @submit.prevent="saveQuery"><input v-model="queryName" aria-label="Saved query name" placeholder="Name this query" maxlength="100"><button type="submit" :disabled="!queryName.trim() || !view.sql.trim() || !!pending">Save query</button></form><div v-for="q in workspace.queries" :key="q.name"><button type="button" class="lab-text-button" @click="view.sql=q.sql">{{ q.name }}</button><button type="button" :aria-label="`Delete saved query ${q.name}`" @click="action('delete-query',{name:q.name})"><Icon name="trash" /></button></div></details><div v-if="queryResult" class="cache-result-heading"><span>{{ queryResult.rows.length }} {{ queryResult.rows.length===1?'row':'rows' }}{{ queryResult.more?' · first 500 shown':'' }} · {{ queryResult.elapsedMs }} ms</span><div class="lab-button-row"><button type="button" @click="download(cacheCSV(queryResult),'cache-query.csv','text/csv')">Export CSV</button><button type="button" @click="download(JSON.stringify(queryResult,null,2),'cache-query.json')">Export JSON</button></div></div><Grid v-if="queryResult" :result="queryResult" @row="row=$event" /></div>
      <div v-if="view.mode==='compare'" class="cache-comparison"><div class="cache-compare-intro"><div><span class="lab-eyebrow">TWO MOMENTS. ONE CLEAR PICTURE.</span><h4>What changed?</h4><p>Compare records and JSON fields. Choose a table to inspect its data.</p></div><button v-if="diff" type="button" @click="download(JSON.stringify({baseline,comparison,...diff},null,2),'cache-comparison.json')"><Icon name="download" />Export table report</button></div><div class="cache-pair"><label><span class="cache-pair-letter">A</span>Baseline<select v-model="view.baseline" @change="pairChanged"><option value="">Choose baseline</option><option v-for="s in snapshots" :key="s.id" :value="s.id">{{ s.name }} · {{ cacheDate(s.createdAt) }}</option></select></label><Icon name="arrow" /><label><span class="cache-pair-letter">B</span>Comparison<select v-model="view.comparison" @change="pairChanged"><option value="">Choose comparison</option><option v-for="s in snapshots" :key="s.id" :value="s.id">{{ s.name }} · {{ cacheDate(s.createdAt) }}</option></select></label></div><div class="cache-diff-controls"><label class="cache-check"><input v-model="view.ignoreVolatile" type="checkbox" @change="compare">Ignore metadata.resourceVersion & managedFields</label><button v-if="comparing" type="button" @click="diffController?.abort()">Cancel comparison</button><button v-else type="button" :disabled="!view.baseline || !view.comparison || view.baseline===view.comparison" @click="compare"><Icon name="refresh" />Compare</button></div><p v-if="view.ignoreVolatile" class="cache-filter-notice">Noise filter is on. Changes only in these two metadata fields are excluded from counts and details.</p><div v-if="!view.baseline || !view.comparison || view.baseline===view.comparison" class="cache-compare-empty"><Icon name="branch" /><h4>Choose two different snapshots.</h4><p>Capture a baseline, make your change in Rancher, then capture again to see the difference.</p></div><div v-if="comparing" class="cache-loading" role="status"><Icon name="refresh" class="lab-spin" />Comparing snapshot contents…</div><template v-if="diff"><div v-for="warning in diff.warnings" :key="warning" class="cache-diff-warning"><Icon name="signal" />{{ warning }}</div><label class="cache-diff-table">Compare table<select v-model="view.compareTable" @change="compare"><option value="">Choose a table · {{ diff.tables.length }} available</option><option v-for="t in diff.tables" :key="t.name" :value="t.name">{{ t.name }}{{ t.kind==='same'?'':` · ${t.kind}` }}</option></select></label><div v-if="!view.compareTable" class="cache-schema-overview"><button v-for="t in diff.tables" :key="t.name" type="button" @click="view.compareTable=t.name;compare()"><Icon name="table" /><span>{{ t.name }}</span><small>{{ t.kind==='same'?'Compare records':t.kind }}</small><Icon name="arrow" /></button></div><template v-else><div class="cache-diff-metrics"><div data-kind="added"><strong>+{{ diff.added }}</strong><span>Added</span></div><div data-kind="removed"><strong>−{{ diff.removed }}</strong><span>Removed</span></div><div data-kind="changed"><strong>{{ diff.changed }}</strong><span>Changed</span></div><div><strong>{{ diff.unchanged }}</strong><span>Unchanged</span></div></div><p class="cache-diff-key">{{ diff.beforeRows }} → {{ diff.afterRows }} rows <i>·</i> {{ diff.keyColumns.length?`Matched by ${diff.keyColumns.join(' + ')}`:'Whole-row comparison' }}</p><details v-if="diff.beforeSql!==diff.afterSql || JSON.stringify(diff.beforeIndexes)!==JSON.stringify(diff.afterIndexes)" class="cache-schema-change"><summary>Schema changed</summary><div><pre>BEFORE
{{ diff.beforeSql || 'Table did not exist' }}
{{ (diff.beforeIndexes || []).join('\n') }}</pre><pre>AFTER
{{ diff.afterSql || 'Table was removed' }}
{{ (diff.afterIndexes || []).join('\n') }}</pre></div></details><p v-if="!diff.changes.length" class="cache-no-changes"><Icon name="check" />No record changes{{ view.ignoreVolatile?' after filtering':'' }} in this table.</p><div class="cache-change-list"><details v-for="(change,index) in diff.changes" :key="index" :data-kind="change.kind"><summary><span class="cache-change-kind">{{ change.kind }}</span><code>{{ change.key }}</code><small v-if="change.fields?.length">{{ change.fields.length }} field {{ change.fields.length===1?'change':'changes' }}</small><Icon name="chevron" /></summary><div v-if="change.fields?.length" class="cache-field-diffs"><div v-for="(field,i) in change.fields" :key="i"><code>{{ field.path }}</code><div><pre data-side="before">{{ field.kind==='added'?'(absent)':JSON.stringify(field.before,null,2) }}</pre><pre data-side="after">{{ field.kind==='removed'?'(absent)':JSON.stringify(field.after,null,2) }}</pre></div></div><p v-if="change.fields.length===200" class="cache-muted">First 200 field changes shown. Expand the full records below for all data.</p></div><details class="cache-full-records"><summary>Full records</summary><div><section v-if="change.before"><span class="lab-eyebrow">BEFORE</span><JsonValue :value="change.before" /></section><section v-if="change.after"><span class="lab-eyebrow">AFTER</span><JsonValue :value="change.after" /></section></div></details></details></div><p v-if="diff.truncated" class="cache-filter-notice">Counts include every scanned row. Details show up to 300 changes within an 8 MiB preview budget.</p></template></template></div>
      <section v-if="row" class="cache-record-inspector" aria-label="Selected record"><div class="cache-section-heading"><div><span class="lab-eyebrow">RECORD INSPECTOR</span><h4>A closer look</h4></div><div class="lab-button-row"><button type="button" @click="copy(row)"><Icon name="copy" />Copy JSON</button><button type="button" aria-label="Close record inspector" @click="row=null"><Icon name="close" /></button></div></div><JsonValue :value="row" /></section>
     </template>
    </main>
   </div>
  </section>
  <footer class="cache-footer"><span><Icon name="lock" />Source preserved. Snapshots stored locally.</span><details v-if="root"><summary>Storage location</summary><code>{{ root }}</code><p>Manage this library with the workspace cleanup controls above.</p></details></footer>
 </div>
</template>
